Create Table Pur_Cod_Status                        -- جدول ترميز حالة الأمر
( Id         BIGINT NOT NULL,                           -- مفتاح رئيسي
  Status_Id  BIGINT Default 1,                          -- حالة الترميز
  Name       VARCHAR(100) NOT NULL,                  -- الاسم
  Rem        VARCHAR(100),                           -- ملاحظات
  Ins_User   BIGINT,  Ins_Date    TIMESTAMP,
  Upd_User   BIGINT,  Upd_Date    TIMESTAMP,
  CONSTRAINT Pur_Cod_Status_PK     PRIMARY KEY (Id  ),
  CONSTRAINT Pur_Cod_Status_UK     UNIQUE      (Name),
  CONSTRAINT Pur_Cod_Status_Ins_FK Foreign Key (Ins_User) References Cpy_User(Id),
